using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.SceneManagement;using LWS.TruckBowling;using LWS.TruckDockDiving;
namespace LWS.TruckSports {public sealed class SportsDeliverySmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();readonly Dictionary<string,string> saved=new Dictionary<string,string>();Keyboard keyboard;Mouse mouse;InputSettings original,probe;string folder;bool done,error;
 [RuntimeInitializeOnLoadMethod]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsDelivery")<0)return;var go=new GameObject("Normal-build injected UI delivery smoke");DontDestroyOnLoad(go);go.AddComponent<SportsDeliverySmoke>();}
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("DeliveryEvidence");Directory.CreateDirectory(folder);foreach(string key in new[]{"DockMatch.Setup.v1","KeepawayMatch.Setup.v1","CurlingMatch.Setup.v1","BaseJumpMatch.Setup.v1"})saved[key]=LWS.TruckSports.SportsPrefs.HasKey(key)?LWS.TruckSports.SportsPrefs.GetString(key):null;original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Delivery software keyboard");mouse=InputSystem.AddDevice<Mouse>("Delivery software pointer");Keys();Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string s,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){error=true;records.Add("ERROR "+s);}}void Check(bool condition,string label){if(!condition)throw new Exception(label);records.Add("PASS "+label);Debug.Log("TS_DELIVERY_PASS "+label);}void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}IEnumerator Wait(Func<bool> p,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!p()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+label);yield return null;}}
 IEnumerator Click(string action){var a=FindObjectsByType<SportsMenuAction>(FindObjectsInactive.Include).First(x=>x.action==action&&x.gameObject.activeInHierarchy);var p=RectTransformUtility.WorldToScreenPoint(null,a.GetComponent<RectTransform>().position);InputSystem.QueueStateEvent(mouse,new MouseState{position=p,buttons=0});yield return Delay(.08f);InputSystem.QueueStateEvent(mouse,new MouseState{position=p,buttons=1});yield return Delay(.09f);InputSystem.QueueStateEvent(mouse,new MouseState{position=p,buttons=0});yield return Delay(.14f);}
 void Update(){if(done)return;try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator child){steps.Push(child);continue;}return;}Finish(error?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));}
 void Finish(int code){done=true;Time.timeScale=1;foreach(var pair in saved)if(pair.Value==null)LWS.TruckSports.SportsPrefs.DeleteKey(pair.Key);else LWS.TruckSports.SportsPrefs.SetString(pair.Key,pair.Value);LWS.TruckSports.SportsPrefs.Save();File.WriteAllLines(Path.Combine(folder,"results.txt"),records);if(keyboard.added)InputSystem.RemoveDevice(keyboard);if(mouse.added)InputSystem.RemoveDevice(mouse);InputSystem.settings=original;Destroy(probe);Application.Quit(code);}
 IEnumerator Run(){yield return Delay(.8f);Check(Application.productName=="Truck Sports"&&Application.companyName!="LWS Truck Sports Validation","normal-company branded standalone startup");Check(SceneManager.GetActiveScene().name==SportsNavigation.Front,"TruckSports is startup scene");Capture("normal-startup");yield return Click("play");Check(FindAnyObjectByType<SportsFrontEnd>().Page==1,"actual injected pointer opens sport selection");Capture("normal-selection");yield return Click("dock");yield return Wait(()=>FindAnyObjectByType<DockMatch>()!=null,5,"Dock menu click");var m=FindAnyObjectByType<DockMatch>();m.setup.count=1;m.setup.players[0].source=BowlingSource.Keyboard;m.setup.players[0].name="Delivery smoke";m.menus.Dirty();yield return Delay(.2f);yield return Click("start");Check(m.Live,"actual injected pointer starts new sport");yield return Delay(.25f);var before=m.truck.body.position;Keys(Key.W);yield return Wait(()=>m.truck.body.position.z>before.z+.6f,5,"actual assigned keyboard driving");Keys();Check(m.truck.Powered&&m.Phase==DockPhase.Approach,"driving remains physical on approach");Capture("normal-driving");yield return Delay(.2f);Keys(Key.Escape);yield return Delay(.08f);Keys();yield return Wait(()=>m.Paused,3,"Escape pause");var frozen=m.truck.body.position;yield return Delay(.25f);Check(m.truck.body.position==frozen,"normal build pause preserves body");Capture("normal-pause");yield return Click("resume");Check(m.Live,"actual pointer resumes without confirmation leakage");yield return Delay(.2f);Keys(Key.Escape);yield return Delay(.08f);Keys();yield return Wait(()=>m.Paused,3,"second pause");yield return Delay(.25f);yield return Click("front");Check(m.menus.Screen==SportsEventScreen.Confirm,"abandonment confirmation remains explicit");yield return Delay(.25f);yield return Click("yes");yield return Wait(()=>FindAnyObjectByType<SportsFrontEnd>()!=null,5,"normal return to collection");Check(FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length==1,"normal return has one listener");Check(!error,"normal-company UI/input smoke has no runtime errors");Capture("normal-return");yield return Delay(.2f);}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}}
